INSERT INTO College VALUES('cmnu7qgbf0016p0itts34ho4r','MS Ramaiah Institute of Technology (MSRIT) – Direct Admission 2026, Courses, Fees, Ranking &amp; Placements','ms-ramaiah-institute-of-technology-admission-2025','Bangalore, Karnataka',replace(replace('\r\n\r\n\r\n  \r\n  \r\n  <title>MS Ramaiah Institute of Technology Admission 2026 – Courses, Fees, Placements &amp; Direct Admission</title>\r\n  \r\n  \r\n  \r\n  \r\n  \r\n  \r\n\r\n\r\n\r\n<h1>MS Ramaiah Institute of Technology Admission 2026</h1>\r\n\r\n<h2>📍 College Overview</h2>\r\n<ul>\r\n  <li><strong>Location:</strong> MSR Nagar, Bangalore – 560054</li>\r\n  <li><strong>Established:</strong> 1962</li>\r\n  <li><strong>Affiliation:</strong> VTU, Belagavi</li>\r\n  <li><strong>Approval:</strong> AICTE, NBA</li>\r\n  <li><strong>Accreditation:</strong> NAAC A, ISO 9001:2008</li>\r\n  <li><strong>Type:</strong> Private, Autonomous</li>\r\n  <li><strong>Managed by:</strong> Gokula Education Foundation</li>\r\n</ul>\r\n\r\n<hr />\r\n\r\n<h2>🏆 Rankings</h2>\r\n<ul>\r\n  <li>#1 under VTU in Karnataka</li>\r\n  <li>#8 among top engineering colleges in India (MHRD)</li>\r\n  <li>Consistently in top 10 private colleges in India</li>\r\n</ul>\r\n\r\n<hr />\r\n\r\n<h2>🎓 Courses &amp; Seat Intake 2026</h2>\r\n<h3>B.E/B.Tech Programs</h3>\r\n<ul>\r\n  <li>Popular Branches: CSE, ISE, ECE, Mechanical, Civil, etc.</li>\r\n  <li>Specializations: AI, Cyber Security, Data Science</li>\r\n  <li>Seats: 60 to 180 depending on branch</li>\r\n  <li>Eligibility: 10+2 with PCM + CET/COMEDK/JEE</li>\r\n</ul>\r\n\r\n<h3>B.Arch Program</h3>\r\n<ul>\r\n  <li>Duration: 5 Years</li>\r\n  <li>Eligibility: NATA + 10+2 with 50% in PCM</li>\r\n</ul>\r\n\r\n<h3>PG Programs</h3>\r\n<ul>\r\n  <li>M.Tech, MBA, MCA, M.Arch</li>\r\n  <li>Eligibility: B.E/B.Tech + PGCET/GATE</li>\r\n</ul>\r\n\r\n<h3>Ph.D Programs</h3>\r\n<ul>\r\n  <li>12+ Research Departments</li>\r\n  <li>Streams: Engineering, Science, Management</li>\r\n</ul>\r\n\r\n<hr />\r\n\r\n<h2>💰 MSRIT Fee Structure 2026</h2>\r\n<table>\r\n  <thead>\r\n    <tr><th>Admission Type</th><th>Annual Fee (INR)</th></tr>\r\n  </thead>\r\n  <tbody>\r\n    <tr><td>CET (Karnataka)</td><td>₹1,30,000</td></tr>\r\n    <tr><td>COMEDK / Management</td><td>₹2,92,000 (varies by branch)</td></tr>\r\n  </tbody>\r\n</table>\r\n<p><strong>Note:</strong> 30% of seats reserved under Management Quota.</p>\r\n\r\n<hr />\r\n\r\n<h2>📝 Admission Process 2026–26</h2>\r\n<ul>\r\n  <li>UG Admission: CET, COMEDK, JEE, NATA</li>\r\n  <li>PG Admission: PGCET, GATE</li>\r\n  <li>Direct Admission through Management Quota</li>\r\n  <li>Online &amp; Offline Mode Available</li>\r\n</ul>\r\n\r\n<hr />\r\n\r\n<h2>💼 Placement Highlights 2026</h2>\r\n<ul>\r\n  <li>Companies Visited: 358+</li>\r\n  <li>Total Offers: 1892</li>\r\n  <li>Highest Package: ₹50 LPA</li>\r\n  <li>Average Package: ₹7.66 LPA</li>\r\n  <li>Top Recruiters: Amazon, Google, Infosys, IBM, Cognizant</li>\r\n</ul>\r\n\r\n<hr />\r\n\r\n<h2>🏫 Campus Facilities</h2>\r\n<ul>\r\n  <li>Advanced Labs &amp; Research Centers</li>\r\n  <li>Wi-Fi Campus, Hostels, Canteens</li>\r\n  <li>Sports Complex, Medical Facilities</li>\r\n</ul>\r\n\r\n<hr />\r\n\r\n<h2>📞 Admission Contact – MSRIT 2026</h2>\r\n<ul>\r\n  <li><strong>Phone:</strong> <a href="tel:7707055155">7707055155</a></li>\r\n  <li><strong>Email:</strong> <a href="mailto:support@collegeadm.org">support@collegeadm.org</a></li>\r\n  <li><strong>Website:</strong> <a href="https://www.msrit.edu" target="_blank" rel="dofollow">www.msrit.edu</a></li>\r\n</ul>\r\n\r\n<hr />\r\n\r\n<h2>🔗 Useful Links</h2>\r\n<ul>\r\n  <li><a href="http://localhost:8080/rvce-bangalore-admission-2026" rel="dofollow">RVCE Bangalore Admission 2026</a></li>\r\n  <li><a href="http://localhost:8080/bmsce-bangalore-admission-2026" rel="dofollow">BMSCE Bangalore Admission 2026</a></li>\r\n  <li><a href="http://localhost:8080" rel="dofollow">College Admission Portal</a></li>\r\n</ul>\r\n\r\n<hr />\r\n\r\n<h2>📈 Top Searches</h2>\r\n<ul>\r\n  <li>MS Ramaiah Institute of Technology Admission 2026</li>\r\n  <li>MSRIT Bangalore Direct Admission</li>\r\n  <li>MSRIT COMEDK Cutoff 2026</li>\r\n  <li>MS Ramaiah College Management Quota Fees</li>\r\n  <li>Top Private Engineering Colleges in Karnataka</li>\r\n</ul>\r\n\r\n\r\n\r\n','\r',char(13)),'\n',char(10)),'Contact for Fees',NULL,'Partner College','/images/colleges/highcompress-msrit-1024x500-1.jpg',NULL,1775904580635,1775910655264,NULL,NULL);
